import os
import queue
import threading
from typing import Generator, Optional

import pyaudio
from google.cloud import speech


class StreamingMicrophoneTranscriber:
    RATE = 16000
    CHUNK = int(RATE / 10)

    def __init__(
        self,
        language_code: str = "en-US",
        sample_rate_hertz: int = RATE,
        chunk_size: int = CHUNK,
        interim_results: bool = True,
        audio_channel_count: int = 1,
    ) -> None:
        self.language_code = language_code
        self.sample_rate_hertz = sample_rate_hertz
        self.chunk_size = chunk_size
        self.interim_results = interim_results
        self.audio_channel_count = audio_channel_count

        self._audio_interface: Optional[pyaudio.PyAudio] = None
        self._audio_stream = None
        self._buff: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._closed = True

        self._client = speech.SpeechClient()

    def __enter__(self) -> "StreamingMicrophoneTranscriber":
        self._audio_interface = pyaudio.PyAudio()
        self._audio_stream = self._audio_interface.open(
            format=pyaudio.paInt16,
            channels=self.audio_channel_count,
            rate=self.sample_rate_hertz,
            input=True,
            frames_per_buffer=self.chunk_size,
            stream_callback=self._fill_buffer,
        )
        self._closed = False
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        if self._audio_stream is not None:
            self._audio_stream.stop_stream()
            self._audio_stream.close()
            self._audio_stream = None
        self._buff.put(None)
        if self._audio_interface is not None:
            self._audio_interface.terminate()
            self._audio_interface = None

    def _fill_buffer(self, in_data, frame_count, time_info, status_flags):
        self._buff.put(in_data)
        return None, pyaudio.paContinue

    def _audio_generator(self) -> Generator[bytes, None, None]:
        while not self._closed:
            chunk = self._buff.get()
            if chunk is None:
                return

            data = [chunk]

            while True:
                try:
                    chunk = self._buff.get(block=False)
                except queue.Empty:
                    break

                if chunk is None:
                    return
                data.append(chunk)

            yield b"".join(data)

    def stream_transcripts(self) -> Generator[dict, None, None]:
        recognition_config = speech.RecognitionConfig(
            encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
            sample_rate_hertz=self.sample_rate_hertz,
            language_code=self.language_code,
            audio_channel_count=self.audio_channel_count,
            model="latest_short",
        )

        streaming_config = speech.StreamingRecognitionConfig(
            config=recognition_config,
            interim_results=self.interim_results,
        )

        requests = (
            speech.StreamingRecognizeRequest(audio_content=content)
            for content in self._audio_generator()
        )

        responses = self._client.streaming_recognize(
            config=streaming_config,
            requests=requests,
        )

        for response in responses:
            for result in response.results:
                if not result.alternatives:
                    continue
                alternative = result.alternatives[0]
                yield {
                    "transcript": alternative.transcript,
                    "is_final": result.is_final,
                    "confidence": getattr(alternative, "confidence", 0.0),
                    "language_code": self.language_code,
                }


def stream_microphone_transcripts(
    language_code: str = "en-US",
) -> Generator[dict, None, None]:
    if not os.getenv("GOOGLE_APPLICATION_CREDENTIALS"):
        raise EnvironmentError(
            "GOOGLE_APPLICATION_CREDENTIALS must be set for Google Cloud Speech-to-Text."
        )

    with StreamingMicrophoneTranscriber(language_code=language_code) as transcriber:
        yield from transcriber.stream_transcripts()


class TranscriptStreamer:
    def __init__(self, language_code: str = "en-US") -> None:
        self.language_code = language_code
        self._transcriber: Optional[StreamingMicrophoneTranscriber] = None
        self._thread: Optional[threading.Thread] = None
        self._results: "queue.Queue[Optional[dict]]" = queue.Queue()
        self._error: Optional[BaseException] = None

    def start(self) -> None:
        if self._thread is not None:
            return

        def run():
            try:
                with StreamingMicrophoneTranscriber(language_code=self.language_code) as t:
                    self._transcriber = t
                    for item in t.stream_transcripts():
                        self._results.put(item)
            except BaseException as exc:
                self._error = exc
            finally:
                self._results.put(None)

        self._thread = threading.Thread(target=run, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        if self._transcriber is not None:
            self._transcriber.close()
        if self._thread is not None:
            self._thread.join(timeout=2.0)

    def transcripts(self) -> Generator[dict, None, None]:
        self.start()
        while True:
            item = self._results.get()
            if item is None:
                if self._error is not None:
                    raise self._error
                break
            yield item
